using namespace std;

// limit for k
const long long LIM = (long long)1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    // dp[i] = number of valid permutations of length i
    // with the described property
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long val = dp[i - 1]; // singleton cycle (i)
        if (i >= 2) {
            long long add = dp[i - 2] * (i - 1); // 2-cycle (i, j) with j < i
            if (add > LIM) add = LIM;
            val += add;
        }
        if (val > LIM) val = LIM;
        dp[i] = val;
    }

    vector<int> perm(n + 1, 0); // 1-based
    vector<bool> used(n + 1, false);

    int pos = 1;
    while (pos <= n) {
        // try to place a singleton at pos
        long long cnt_single = dp[n - pos];
        if (cnt_single >= k) {
            // singleton: cycle (pos)
            perm[pos] = pos;
            used[pos] = true;
            pos++;
        } else {
            k -= cnt_single;
            // need a 2-cycle starting at pos: (pos, j) with j > pos
            // but in our construction, cycles are (i, j) with i > j,
            // and sorted by first element; we are building in order of i.
            // For position pos, we choose partner j (pos+1..n)
            // but must ensure j is unused and we count permutations
            // for remaining n - pos - 1 positions.
            int remaining = n - pos - 1;
            // we must iterate possible partner j
            for (int j = pos + 1; j <= n; ++j) {
                // number of permutations if we choose partner j
                long long cnt = dp[remaining];
                if (cnt >= k) {
                    // choose this j
                    perm[pos] = j;
                    perm[pos + 1] = pos;
                    used[pos] = used[j] = true;
                    pos += 2;
                    break;
                } else {
                    k -= cnt;
                }
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << ' ';
        cout << perm[i];
    }
    cout << '\n';
    return 0;
}
